class Solution {
    private List<String> res = new ArrayList<>();
    private String num;
    private int target;

    public List<String> addOperators(String num, int target) {
        this.num = num;
        this.target = target;
        res.clear();
        backtrack(0, "", 0, 0);
        return res;
    }

    private void backtrack(int idx, String path, long total, long prev) {
        if (idx == num.length()) {
            if (total == target) res.add(path);
            return;
        }
        for (int i = idx; i < num.length(); i++) {
            if (i > idx && num.charAt(idx) == '0') break;
            String part = num.substring(idx, i + 1);
            long val = Long.parseLong(part);
            if (idx == 0) {
                backtrack(i + 1, part, val, val);
            } else {
                backtrack(i + 1, path + "+" + part, total + val, val);
                backtrack(i + 1, path + "-" + part, total - val, -val);
                backtrack(i + 1, path + "*" + part, total - prev + prev * val, prev * val);
            }
        }
    }
}

