var addOperators = function(num, target) {
    const res = [];
    const n = num.length;
    function backtrack(idx, path, total, prev) {
        if (idx === n) {
            if (total === target) res.push(path);
            return;
        }
        for (let i = idx; i < n; i++) {
            if (i > idx && num[idx] === '0') break;
            const part = num.slice(idx, i + 1);
            const val = parseInt(part, 10);
            if (idx === 0) {
                backtrack(i + 1, part, val, val);
            } else {
                backtrack(i + 1, path + '+' + part, total + val, val);
                backtrack(i + 1, path + '-' + part, total - val, -val);
                backtrack(i + 1, path + '*' + part, total - prev + prev * val, prev * val);
            }
        }
    }
    backtrack(0, '', 0, 0);
    return res;
};
